  OR (SELECT count(DISTINCT x->>'public_path') FROM jsonb_array_elements(j)x)<>7 THEN
  RAISE EXCEPTION 'Invalid gazpacho payload';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND
   (r.recipe_group_id<>g OR r.language<>'es' OR r.slug<>b->>'slug' OR r.public_path<>b->>'public_path'
    OR r.source_url IS DISTINCT FROM b->>'source_url' OR r.created_at<>(b->>'created_at')::timestamptz
    OR r.published_at IS DISTINCT FROM (b->>'published_at')::timestamptz)) THEN
  RAISE EXCEPTION 'Historical identity/date divergence before idempotent or initial publication';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(j)x WHERE (x->>'recipe_group_id')::uuid<>g
    OR x->>'language' NOT IN ('es','de','en','fr','it','ja','pt')) THEN
  RAISE EXCEPTION 'Unexpected group or language in publication payload';
 END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)=7
  AND NOT EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::public.recipes,j)x LEFT JOIN public.recipes r ON r.id=x.id
    WHERE r.id IS NULL OR NOT r.published OR r.editorial_status<>'published' OR r.recipe_group_id<>x.recipe_group_id
      OR r.language<>x.language OR r.slug<>x.slug OR r.public_path<>x.public_path OR r.title IS DISTINCT FROM x.title OR r.excerpt IS DISTINCT FROM x.excerpt OR r.summary IS DISTINCT FROM x.summary OR r.ingredients IS DISTINCT FROM x.ingredients OR r.steps IS DISTINCT FROM x.steps OR r.category IS DISTINCT FROM x.category OR r.prep_time_minutes IS DISTINCT FROM x.prep_time_minutes OR r.cook_time_minutes IS DISTINCT FROM x.cook_time_minutes OR r.total_time_minutes IS DISTINCT FROM x.total_time_minutes OR r.servings IS DISTINCT FROM x.servings OR r.image_url IS DISTINCT FROM x.image_url OR r.content_html IS DISTINCT FROM x.content_html OR r.notes IS DISTINCT FROM x.notes OR r.difficulty IS DISTINCT FROM x.difficulty OR r.course IS DISTINCT FROM x.course OR r.cuisine IS DISTINCT FROM x.cuisine OR r.keywords IS DISTINCT FROM x.keywords OR r.nutrition IS DISTINCT FROM x.nutrition OR r.gallery IS DISTINCT FROM x.gallery OR r.seo IS DISTINCT FROM x.seo OR r.source_url IS DISTINCT FROM x.source_url) THEN
  RAISE NOTICE 'Gazpacho already matches7/7; no mutation'; RETURN;
 END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)<>1
  OR NOT EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND r.recipe_group_id=g
    AND r.language='es' AND NOT r.published AND md5(to_jsonb(r)::text)=b->>'expected_row_md5') THEN
  RAISE EXCEPTION 'Reserved gazpacho state changed; reconcile before retry';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_populate_recordset(NULL::public.recipes,j)x
  ON r.id=x.id OR r.public_path=x.public_path OR (r.language=x.language AND r.slug=x.slug)
  WHERE r.id<>x.id OR r.recipe_group_id<>x.recipe_group_id OR r.language<>x.language) THEN
  RAISE EXCEPTION 'Gazpacho recipe identity/route collision';
 END IF;
 IF EXISTS(SELECT 1 FROM public.content_pages c JOIN jsonb_populate_recordset(NULL::public.recipes,j)x
  ON c.public_path=x.public_path OR (c.language=x.language AND c.slug=x.slug)) THEN
  RAISE EXCEPTION 'Gazpacho content_page route collision';
 END IF;
 SELECT md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' ORDER BY r.id),'')) INTO outside_checksum
  FROM public.recipes r WHERE r.recipe_group_id<>g;
 SELECT count(*) INTO es_count FROM public.recipes WHERE language='es' AND published;
 UPDATE public.recipes r SET title=x.title, excerpt=x.excerpt, summary=x.summary, ingredients=x.ingredients, steps=x.steps, category=x.category, prep_time_minutes=x.prep_time_minutes, cook_time_minutes=x.cook_time_minutes, total_time_minutes=x.total_time_minutes, servings=x.servings, image_url=x.image_url, content_html=x.content_html, notes=x.notes, difficulty=x.difficulty, course=x.course, cuisine=x.cuisine, keywords=x.keywords, nutrition=x.nutrition, gallery=x.gallery, seo=x.seo,editorial_status='published',ready_at=now(),published=true
  FROM jsonb_populate_recordset(NULL::public.recipes,j)x WHERE r.id=x.id AND x.language='es';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'Expected1ES update, got%',n; END IF;
 INSERT INTO public.recipes(id,recipe_group_id,language,slug,public_path,source_url,title,excerpt,summary,ingredients,steps,category,prep_time_minutes,cook_time_minutes,total_time_minutes,servings,image_url,content_html,notes,difficulty,course,cuisine,keywords,nutrition,gallery,seo,editorial_status,ready_at,published) SELECT x.id,x.recipe_group_id,x.language,x.slug,x.public_path,x.source_url,x.title,x.excerpt,x.summary,x.ingredients,x.steps,x.category,x.prep_time_minutes,x.cook_time_minutes,x.total_time_minutes,x.servings,x.image_url,x.content_html,x.notes,x.difficulty,x.course,x.cuisine,x.keywords,x.nutrition,x.gallery,x.seo,'published',now(),true FROM jsonb_populate_recordset(NULL::public.recipes,j)x WHERE x.language<>'es';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>6 THEN RAISE EXCEPTION 'Expected6translations, got%',n; END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)<>7
  OR (SELECT count(DISTINCT language) FROM public.recipes WHERE recipe_group_id=g AND published AND editorial_status='published')<>7
  OR EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::public.recipes,j)x LEFT JOIN public.recipes r ON r.id=x.id
    WHERE r.id IS NULL OR r.recipe_group_id<>x.recipe_group_id OR r.language<>x.language
      OR r.slug<>x.slug OR r.public_path<>x.public_path OR NOT r.published OR r.title IS DISTINCT FROM x.title OR r.excerpt IS DISTINCT FROM x.excerpt OR r.summary IS DISTINCT FROM x.summary OR r.ingredients IS DISTINCT FROM x.ingredients OR r.steps IS DISTINCT FROM x.steps OR r.category IS DISTINCT FROM x.category OR r.prep_time_minutes IS DISTINCT FROM x.prep_time_minutes OR r.cook_time_minutes IS DISTINCT FROM x.cook_time_minutes OR r.total_time_minutes IS DISTINCT FROM x.total_time_minutes OR r.servings IS DISTINCT FROM x.servings OR r.image_url IS DISTINCT FROM x.image_url OR r.content_html IS DISTINCT FROM x.content_html OR r.notes IS DISTINCT FROM x.notes OR r.difficulty IS DISTINCT FROM x.difficulty OR r.course IS DISTINCT FROM x.course OR r.cuisine IS DISTINCT FROM x.cuisine OR r.keywords IS DISTINCT FROM x.keywords OR r.nutrition IS DISTINCT FROM x.nutrition OR r.gallery IS DISTINCT FROM x.gallery OR r.seo IS DISTINCT FROM x.seo OR r.source_url IS DISTINCT FROM x.source_url) THEN
  RAISE EXCEPTION 'Gazpacho7/7 final content verification failed';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND
   (r.slug<>b->>'slug' OR r.public_path<>b->>'public_path' OR r.source_url IS DISTINCT FROM b->>'source_url'
    OR r.created_at<>(b->>'created_at')::timestamptz OR r.published_at IS DISTINCT FROM (b->>'published_at')::timestamptz)) THEN
  RAISE EXCEPTION 'Gazpacho historical identity/date preservation failed';
 END IF;
 IF outside_checksum IS DISTINCT FROM(SELECT md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' ORDER BY r.id),'')) FROM public.recipes r WHERE r.recipe_group_id<>g)
  OR (SELECT count(*) FROM public.recipes WHERE language='es' AND published)<>es_count+1 THEN
  RAISE EXCEPTION 'Unexpected change outside gazpacho group';
 END IF;
 RAISE NOTICE 'Gazpacho verified7/7 within surrounding atomic lote04 transaction';
END
$gazpacho$;
